import Foundation

private typealias E = EvidenceSeed

/// More everyday cases, written compactly with the shared helper: gas drive-offs, window breaking, package theft,
/// false reports, fence disputes, and the other small matters that fill a real county's docket.
extension StoryCases {
    static let batchAM: [CaseTemplate] = [gasDriveOff, bottleWindow, libraryBan, lawnMowerNeighbor, leashFight, stolenCarReport,
                                          packageThief, golfCartJoyride, refusedID, oxyBottle, dineDash, fenceKick, walletCard]

    static let gasDriveOff = FollowUpCases.followUp(
        key: "story.gasDriveOff", category: .property,
        headlines: ["Driver Filled Tank and Drove Off Without Paying", "Gas Station Camera Catches Drive-Off Suspect"],
        law: "misdLarceny", threshold: 5, spec: "Stole $64 in motor fuel from a gas station, on {DATE}.", ages: 19...55, victim: false,
        summary: "A gas station camera recorded {D} filling a tank with $64 of fuel at pump six at 11:20 p.m. on {DATE}, then driving away without going inside. The plate was readable and came back to {D.him}. {DL} says the card reader at the pump was broken, that {D.he} meant to pay inside, and that {D.he} was rushing to a sick relative's house.",
        state: [E(.video, 3, "Pump Camera", "{D} fills the tank, hangs up the nozzle, and drives off at 11:24 p.m."),
                E(.document, 2, "Plate Return", "The plate on the camera is registered to {D}.")],
        defense: [E(.document, 2, "Pump Report", "The station's own log shows pump six's card reader was down that night.")],
        witnessRole: "Gas station clerk",
        exam: [.direct("What did the camera show?", "\"{DL} filling up at pump six and leaving without coming in.\""),
               .direct("Was the card reader broken?", "\"It was down. A sign said to pay inside.\""),
               .direct("What time did this happen?", "\"At 11:20 p.m., on a quiet night. I was working the counter alone, and I watched the pumps on the monitor behind me.\""), .direct("How much fuel did {DL} pump?", "\"$64 worth at pump six. The pump log shows it ran for about four minutes and shut off at the preset amount.\""), .direct("What did you see when {DL} left?", "\"The car pulled out without anyone coming inside. I read the plate off the camera and wrote it down.\""), .direct("How was {DL} identified?", "\"The plate came back to {D.him}. I gave the number to the sheriff's office, and a deputy called {D.him} the next morning.\""),
                    .cross("The sign was inside the store.", "\"Yes. It was on the window too.\""),
               .cross("{D.He} came back later?", "\"The next morning, to pay. After the sheriff called.\""),
                    .cross("The card reader at pump six was down, wasn't it?", "\"Yes. My own log shows it. A sign on the pump said to pay inside.\""), .cross("{DL} came back to pay the next morning?", "\"Yes, after the deputy called. {D.He} paid in full and apologized.\""), .cross("No one told {DL} to pay inside?", "\"The sign did. A person who did not read it could have missed it, and I did not speak to {D.him}.\"")],
        theory: ("{D} took $64 of gas and left, and only came back after a deputy called.", "A broken reader, a sick relative, and a payment made as soon as {D.he} could."),
        allocution: "\"My cousin was in the hospital, and I wasn't thinking straight. The card reader at that pump was broken, and I meant to go inside and pay, but I was rushing to a sick relative's side. I should have stopped and told the clerk. I'm sorry for the sixty-four dollars, and I'll pay it back.\"",
        truths: ("{DL} had driven off from two other stations in the same month.", "{DL}'s relative was admitted to the hospital that night, records show."),
        defendant: [.direct("Why didn't you pay?", "\"My cousin was in the hospital and I wasn't thinking.\""),
               .direct("Did you come back?", "\"The next morning, when I saw the call.\""),
               .direct("Why did you leave without paying?", "\"My cousin was in the hospital and I had just gotten a call. I filled the tank without thinking and drove off.\""),
               .direct("Did you see a sign at the pump?", "\"No. I looked for the card reader and it was dark. I did not see a sign about paying inside.\""),
               .direct("What did you do the next morning?", "\"A deputy called me, and I went right to the station and paid in full. I was embarrassed.\""),
               .direct("Did you mean to drive off without paying?", "\"No. I meant to pay inside, and I forgot because of the call. I would never do that on purpose.\""),
               .cross("A sign said pay inside.", "\"I didn't see the sign saying to pay inside.\""),
               .cross("Nobody called you until the next day.", "\"That is why I went myself. When no one called, I drove to the station and asked what I owed.\""),
               .cross("The sign was on the window too.", "\"I did not see it. I was not looking at the windows, and I am sorry.\""),
               .cross("You drove off at 11:24.", "\"I did, and I was distracted. I should have gone in and told the clerk what happened.\""),
                    .cross("The log shows the reader was down that night.", "\"It was down. I wish I had gone in and paid. I did not see the sign.\"")],
        openings: ("At 11:20 p.m. {D} pumped $64 of fuel at pump six and drove off without going inside, and the camera caught the plate. The station's own log shows the pump's card reader was down that night.", "The defense will say {D} meant to pay inside, was distracted by a call about a cousin in the hospital, and went to pay the next morning as soon as a deputy called."),
        closings: ("$64 of fuel, a pump with a sign saying to pay inside, a readable plate, and a car that left without anyone coming in.", "A man who drove up under the lights with his own plate, paid in full the next day, and apologized did not mean to steal. The State must prove {D} drove off intending never to pay for the fuel."),
        timeline: [(0, "11:20 p.m.: fuel taken."), (1, "{DL} returns to pay after a deputy calls.")],
        identified: "The pump camera and the plate.", impact: nil)

    static let bottleWindow = FollowUpCases.followUp(
        key: "story.bottleWindow", category: .property,
        headlines: ["Bar Window Smashed After Closing; Customer Charged", "Man Says He Was Thrown Out and Lost His Temper"],
        law: "injuryPersonalProperty", threshold: 5, spec: "Willfully and wantonly injured personal property of {V}, a plate glass window, causing damage of $1,400, on {DATE}.", ages: 21...52, victim: true,
        summary: "After being cut off and asked to leave a bar at 1:50 a.m. on {DATE}, {D} walked outside, threw a beer bottle through the front plate glass window, and stood on the sidewalk until deputies arrived. {V}, the bar owner, put the replacement cost at $1,400. {DL} says {D.he} threw the bottle at a trash can and the window was already cracked.",
        state: [E(.video, 3, "Front Camera", "{D} throws a bottle at the window and the glass falls in sheets."),
                E(.document, 2, "Glass Estimate", "$1,400 for a new plate glass pane and installation.")],
        defense: [E(.statement, 1, "Cracked Glass", "A regular says the window had a crack in it for months.")],
        witnessRole: "Bar owner",
        exam: [.direct("What did you see?", "\"{DL} threw a bottle at my front window. The whole pane came down.\""),
               .direct("What did it cost?", "\"$1,400, and a night's business.\""),
               .direct("What time did it happen?", "\"About 1:50 in the morning. I had cut {DL} off and asked {D.him} to leave, and {D.he} went out the front door.\""), .direct("What did you see through the window?", "\"{DL} outside on the sidewalk, picking up a beer bottle from a table by the door, and winding up like a pitcher.\""), .direct("What happened to the window?", "\"The whole pane came down in sheets. Glass landed on two tables and the floor, and a customer had to move.\""), .direct("What did {DL} do afterward?", "\"Stood on the sidewalk and then sat on the curb until the deputies arrived. {D.He} did not run.\""),
                    .cross("The window was cracked.", "\"A small crack in the corner. It was holding.\""),
               .cross("{D.He} waited for the deputies.", "\"{D.He} sat on the curb.\""),
                    .cross("The window had a crack in it already, didn't it?", "\"A small one in the lower corner. It had been there for months, and the glass company said it was holding.\""), .cross("{DL} did not go back in the bar?", "\"No. {D.He} stayed outside the whole time. {D.He} did not threaten anyone.\""), .cross("You cut {DL} off because of how much {D.he} had drunk?", "\"I did. {D.He} was slurring, and I asked {D.him} to leave quietly.\"")],
        theory: ("{D} threw a bottle through a window after being asked to leave.", "A bottle meant for a trash can and a window that was already weak."),
        allocution: "\"I'd been thrown out of the bar, and I was angry, but I threw that bottle at the trash can, not the window. I missed, and I think the glass was already cracked. I stayed on the sidewalk until the deputies came. I'm sorry to the owner for the trouble, and I'll help with whatever the court decides.\"",
        truths: ("{DL}'s text that night said, \"watch what happens to that bar.\"", "The window's frame had a crack running the full length, a glazier later confirmed."),
        defendant: [.direct("What did you throw the bottle at?", "\"The trash can. I missed.\""),
               .direct("Why were you angry?", "\"They threw me out for no reason.\""),
               .direct("Why were you thrown out?", "\"The bartender said I had too much, and I felt it was for no reason. I had only had a few drinks.\""),
               .direct("What did you do after you left the bar?", "\"I stood outside, angry. I picked up a bottle from a table near the door, and I was going to throw it at a trash can.\""),
               .direct("What were you aiming at?", "\"The trash can on the sidewalk. I missed, and the bottle hit the window instead.\""),
               .direct("What did you do when the glass broke?", "\"I stood there in shock. I did not run, and I sat down on the curb and waited for the deputies.\""),
               .cross("You stood there afterward.", "\"I stood there afterward because I was in shock.\""),
               .cross("The video shows you aiming at the window.", "\"The video shows me aiming at the window, but it was dark.\""),
               .cross("The window cost $1,400.", "\"I know. I told the deputy I would pay for it, and I still will.\""),
                    .cross("The video shows your arm go back and forward.", "\"It does. I threw the bottle at the can, and the can was behind the window.\""),
                    .cross("You had been cut off and told to leave.", "\"I had. I was angry about it, and I did not think about the window.\"")],
        openings: ("After being cut off and asked to leave a bar at 1:50 a.m., {D} walked outside, threw a beer bottle through the front plate glass window, and stood on the sidewalk until deputies arrived. {V}, the owner, put the replacement cost at $1,400.", "The defense will say {D} threw the bottle at a trash can, missed in the dark, and that the window already had a crack. {D} stayed, shocked, and offered to pay."),
        closings: ("A bottle thrown through a plate glass window by a customer who had just been cut off, caught on the front camera, $1,400 of damage, and a night's business lost. {D} did not deny it.", "The window was cracked, the bottle was aimed at a trash can in the dark, and {D} stayed and offered to pay. The State must prove {D} meant to hit the window."),
        timeline: [(0, "1:50 a.m.: removed from the bar; bottle thrown.")],
        identified: "The bar's front camera and the owner's call.", impact: "\"I've owned that place for nineteen years, and I've never had anything like that happen. A bottle through the front window cost me the replacement glass and a weekend of business. It's not about the money as much as how scary it was to watch it happen.\"")

    static let libraryBan = FollowUpCases.followUp(
        key: "story.libraryBan", category: .property,
        headlines: ["Man Banned From Library Returns, Charged With Trespass", "Trespass Charge After Notice Not to Return"],
        law: "trespass2", threshold: 5, spec: "Entered and remained on the premises of the county public library after being notified not to enter, on {DATE}.", ages: 22...65, victim: false,
        summary: "The county library gave {D} a written notice not to return for six months after {D.he} was caught sleeping in the stacks and arguing with a librarian. On {DATE}, a librarian saw {DL} reading at a table, called deputies, and {D.he} was arrested. {DL} says {D.he} never received the notice, since it was mailed to a shelter {D.he} had left, and that the library is a public building.",
        state: [E(.document, 3, "Notice of Trespass", "A letter dated four months earlier banning {D} for six months; mailed to {D}'s last known address."),
                E(.statement, 2, "Librarian", "The librarian who wrote the notice recognized {D} immediately.")],
        defense: [E(.document, 2, "Shelter Record", "{D} left the shelter two days before the notice was mailed.")],
        witnessRole: "Library branch manager",
        exam: [.direct("What did you do after the incident?", "\"We mailed a notice to the address we had.\""),
               .direct("What did {DL} do on {DATE}?", "\"Sat at a table reading a newspaper. I called deputies.\""),
               .direct("How long have you managed this branch?", "\"Nine years. I supervise the staff, the front desk and the policies, including who is banned and for how long.\""), .direct("What happened with {DL} four months before?", "\"{DL} was caught sleeping in the stacks, and then argued with a librarian when she woke {D.him}. We wrote a notice banning {D.him} for six months.\""), .direct("How was the notice delivered?", "\"By mail to the last address we had on file for {D.him}. We did not have a way to hand it to {D.him}.\""), .direct("What did you see on the day of the arrest?", "\"A librarian called me and said {DL} was sitting at a table reading a newspaper. I recognized the name from the notice and called deputies.\""),
                    .cross("Was {D.he} disruptive?", "\"Not that day. {D.He} wasn't disruptive that day.\""),
               .cross("Did you hand {D.him} the notice?", "\"We didn't hand {D.him} the notice, we mailed it.\""),
                    .cross("{DL} was not disruptive that day?", "\"No. {D.He} was reading a newspaper and using a computer. Nobody complained about {D.him}.\""), .cross("The notice went to a shelter address?", "\"It went to the address we had. We learned later that {D.he} had left the shelter two days before the notice was mailed.\""), .cross("You never spoke to {DL} about the ban in person?", "\"I did not. The librarian who wrote the notice spoke to {D.him} after the incident, but the ban was in writing.\"")],
        theory: ("{D} was told in writing not to return, and did.", "{D} never got the notice, and a public library should not turn away a reader."),
        allocution: "\"I never received that notice, because it was mailed to a shelter I had already left. I was sitting at a table reading, and I thought the library was open to everyone. I'm sorry for the misunderstanding with the librarian. I love that place, and I'd like a chance to explain myself.\"",
        truths: ("The shelter manager said {D} had asked for his mail every week.", "{DL} used the library to look for jobs and had no complaints on file."),
        defendant: [.direct("Did you get the notice?", "\"No. I'd left the shelter.\""),
               .direct("Why were you there?", "\"To read the paper and use the computer.\""),
               .direct("What do you use the library for?", "\"To read the newspaper and use the computers for job applications. I do not have a computer at home.\""),
               .direct("Why did you fall asleep in the stacks?", "\"I had been awake for two nights, and I was tired. I sat down with a book and nodded off.\""),
               .direct("What happened with the librarian?", "\"She woke me up, and I snapped at her. I was embarrassed and angry, and I said something I should not have.\""),
               .direct("Did you ever see the notice?", "\"No. I had left the shelter, and the mail did not reach me. I did not know I was banned.\""),
               .cross("You were told once not to return.", "\"I was told once not to return, but not in person.\""),
               .cross("You slept there before.", "\"Once. I was tired, and I fell asleep in a chair.\""),
               .cross("You came back four months later.", "\"I did, because I needed the computer. I did not think a single argument meant I was banned.\""),
                    .cross("You were never handed the notice.", "\"I was not. I did not know about it, and I am not sure I would have believed it.\""),
                    .cross("A librarian recognized you at once.", "\"She did, and she called deputies. I did not argue when they came.\"")],
        openings: ("The county library gave {D} a written notice not to return for six months after {D} was caught sleeping in the stacks and arguing with a librarian. The notice was mailed, and when {D} was seen reading at a table four months later, deputies were called and {D} was arrested.", "The defense will say {D} never received the notice because {D} had left the shelter two days before it was mailed, and was only reading the paper and using a computer. {D} was not disruptive."),
        closings: ("A written notice banning {D} for six months, mailed to the last known address, and four months later {D} was sitting at a table in the library.", "A man who left a shelter two days before a notice was mailed never saw it. The State must prove {D} knew he was banned when {D.he} came back."),
        timeline: [(-120, "Notice of trespass mailed."), (0, "Afternoon: {DL} found reading at a library table.")],
        identified: "The librarian's call.", impact: nil)

    static let lawnMowerNeighbor = FollowUpCases.followUp(
        key: "story.lawnMowerNeighbor", category: .property,
        headlines: ["Neighbor's Riding Mower Missing From Shed, Found Next Door", "Man Says He Borrowed Mower, Neighbor Says He Stole It"],
        law: "misdLarceny", threshold: 5, spec: "Stole a riding lawn mower valued at $900 belonging to {V}, on {DATE}.", ages: 28...68, victim: true,
        summary: "{V}'s riding mower disappeared from an unlocked shed on {DATE}, after {V} refused to lend it to {D}, a neighbor, because {DL} had broken a blade the year before. A week later, {V} saw the mower in {DL}'s backyard with the blade deck freshly cleaned. {DL} says {V} had told {D.him} to \"use it whenever,\" and that {D.he} was going to return it after cutting {D.his} yard.",
        state: [E(.physical, 3, "The Mower", "{V}'s mower with a serial number match, in {D}'s backyard.", .search),
                E(.statement, 2, "Refusal", "{V} says {V.he} told {D} no a few days earlier, in front of a neighbor.")],
        defense: [E(.statement, 1, "Standing Permission", "{DL} says {V} had said, a year earlier, to \"use it whenever.\"")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("Where was the mower?", "\"In {DL}'s backyard, deck washed, tall grass cut around it.\""),
               .direct("What did {DL} say?", "\"That {V} told {D.him} to use it whenever.\""),
               .direct("How did the mower go missing?", "\"{V}'s riding mower disappeared from an unlocked shed. It was gone when {V} checked on a Tuesday, and there were tire marks on the grass.\""),
               .direct("What had happened between {V} and {DL}?", "\"{V} had told {DL} no a few days earlier, in front of a neighbor, when {DL} asked to borrow the mower. A blade had been broken the year before.\""),
               .direct("What did {DL} say?", "\"That {V} had told {D.him} a year earlier to use it whenever. {D.He} said {D.he} took it because it was a standing offer.\""),
               .direct("How did {V} describe the refusal?", "\"{V} said {V.he} told {D} no, plainly, in front of a neighbor, because of the broken blade. The neighbor confirmed it when I asked.\""),
                    .cross("{DL} didn't hide it.", "\"No. It was in plain view.\""),
               .cross("{V} had lent it before.", "\"Once, yes. {V} had lent it before, once.\""),
               .cross("{V} had lent {DL} the mower before, hadn't {V.he}?", "\"Once, a year ago. It was the time the blade was broken, and {V} said never again.\""),
               .cross("{DL} did not hide the mower?", "\"No. It was in plain view in {D.his} yard, and a neighbor could see it from the street.\""),
               .cross("The neighbor heard {V} say no?", "\"A neighbor was present for the refusal, and said so. {DL} says {D.he} did not hear it.\""),
                    .cross("{DL} offered to pay for the blade last year?", "\"{D.He} did, according to {V}. {V} still did not want {D.him} to use it again.\"")],
        theory: ("{D} took a mower {V} had just refused to lend.", "A neighbor with standing permission who borrowed it openly."),
        allocution: "\"I borrowed that mower, because {V} always told me to use it whenever. I meant to return it after cutting my own yard. I did break a blade last year, and I know that was a sore point between us. I'm sorry that {V} saw it as taking. I'd like to patch things up and pay for any damage.\"",
        truths: ("A neighbor heard {V} refuse {DL} the day before the theft.", "{V} had told {DL} to use it whenever, a neighbor later recalled."),
        defendant: [.direct("Did you take the mower?", "\"I borrowed it. {V.He} always said I could.\""),
                    .direct("When?", "\"Last year {V.he} said use it whenever.\""),
                    .direct("How did you get the mower?", "\"I borrowed it. {V} always said I could use it, and I thought that was still true.\""), .direct("When did {V} give you permission?", "\"A year ago, when I borrowed it the first time. {V} said use it whenever, and I never heard otherwise.\""), .direct("Why did you wash the deck?", "\"To be nice. It was dirty, and I wanted to return it clean, which I would have done the next day.\""), .direct("Did you ask first?", "\"Not this time. I went to the shed and saw it, and I figured {V} would not mind.\""),
                    .cross("{V} said no the day before.", "\"I didn't hear {V} say no the day before.\""),
                    .cross("You washed the deck.", "\"I washed the deck to be nice.\""),
                    .cross("{V} said no the day before.", "\"I did not hear {V} say no the day before. I was not there, and nobody told me.\""), .cross("You broke the blade last year.", "\"I did, and I fixed it. {V} did not say I could not use it again.\""), .cross("You took it from an unlocked shed at night.", "\"I did. I should have knocked. It was not locked, and I did not think of it as stealing.\"")],
        openings: ("{V}'s riding mower disappeared from an unlocked shed after {V} refused to lend it to {D}, a neighbor, because {D} had broken a blade the year before. A week later {V} saw it in {D}'s backyard with the deck freshly cleaned.", "The defense will say {V} had told {D} a year earlier to use the mower whenever, that {D} did not hear any refusal, and that {D} washed the deck to be nice. {D} left it in plain view."),
        closings: ("A refusal in front of a neighbor, an unlocked shed, and the mower in {D}'s backyard with the deck washed a week later.", "A standing permission, a mower left in plain view, and no refusal that {D} heard. The State must prove {D} knew {V} had said no."),
        timeline: [(-1, "{V} refuses to lend the mower."), (0, "The mower disappears from the shed.")],
        identified: "{V} saw the mower next door.", impact: "\"It was my husband's mower, and he's gone now, so it meant more than the money. I told the neighbor no because of what happened to the blade last year, and it was taken from my shed anyway. I've kept the shed locked since, and I hate that it came to that.\"")

    static let leashFight = FollowUpCases.followUp(
        key: "story.leashFight", category: .violent,
        headlines: ["Dog Walk Argument Ends in Shove and a Charge", "Neighbors Dispute Who Started Park Fight"],
        law: "simpleAssault", threshold: 5, spec: "Assaulted {V} by pushing {V.him} to the ground, on {DATE}.", ages: 24...66, victim: true,
        summary: "{D}'s unleashed dog ran at {V}'s small dog in a county park on {DATE}. {V} yelled, and {DL} yelled back. According to {V}, {DL} shoved {V.him} to the ground and {V} scraped {V.his} hands. {DL} says {V} swung a leash at {D.his} dog and {D.he} pushed {V.him} away to protect it.",
        state: [E(.statement, 2, "Witness Statement", "A jogger saw {D} shove {V} but not the beginning."),
                E(.document, 1, "Urgent Care Note", "Scraped palms and a bruised hip.")],
        defense: [E(.statement, 2, "Leash", "A second walker says {V} swung the leash at {D}'s dog first.")],
        witnessRole: "Park jogger",
        exam: [.direct("What did you see?", "\"I saw {D} pushing {V} hard enough that {V.he} fell.\""),
               .direct("What happened before?", "\"I didn't see. I heard shouting.\""),
               .direct("What were you doing at the park?", "\"Jogging on the path along the dog area. I saw {V} walking a small dog and {D} with a larger dog, off its leash.\""),
               .direct("What did you see first?", "\"{D.his} dog running at {V}'s small dog. {V} yelled, and {DL} yelled back, and then they were arguing.\""),
               .direct("What injuries did {V} have?", "\"Scraped palms and a bruised hip, according to the urgent care note I saw later.\""),
               .direct("What did you do after {V} fell?", "\"I ran over and asked if {V.he} was all right. {V} was scraped up and angry, and {D} stood a few feet away holding the dog.\""),
                    .cross("{V} had a leash in hand.", "\"Yes. {V} had a leash in hand.\""),
               .cross("The dog ran at {V}'s dog.", "\"I think the dog ran at {V}'s dog.\""),
               .cross("You did not see the beginning, did you?", "\"No. I heard shouting and then I saw the shove, and I came over after {V} fell.\""),
               .cross("{D}'s dog was off its leash?", "\"It was loose, and it ran toward {V}'s dog. I cannot say more about what the dog did.\""),
                    .cross("You do not know who swung the leash?", "\"I did not see that. I only saw the push, and I came over after {V} fell.\"")],
        theory: ("{D} shoved a man to the ground over a dog.", "A defender of a dog against a swinging leash."),
        allocution: "\"{V} swung a leash at my dog, and I pushed {V.him} away without thinking. I did not mean for {V.him} to fall and scrape {V.his} hands. I'm sorry that it happened in a park where everyone goes to relax. I should have kept my dog on a leash, and I'll apologize.\"",
        truths: ("{DL} had been warned twice about the dog being off leash.", "{V} told a friend afterward, \"I swung first, I admit it.\""),
        defendant: [.direct("What happened?", "\"{V} swung the leash at my dog. I pushed {V.him} off.\""),
               .direct("Did you mean for {V.him} to fall?", "\"No. I didn't mean for {V.him} to fall.\""),
               .direct("What happened with your dog?", "\"It ran toward {V}'s dog, as it does when it sees another dog. I called it, and it did not come.\""),
               .direct("What did {V} do?", "\"{V} swung the leash at my dog, hard, and I was afraid {V.he} would hit it. I shouted at {V.him}, and {V.he} came toward me.\""),
               .direct("How did you push {V}?", "\"With my hands, to get {V.him} away from my dog. I did not shove {V.him} to the ground on purpose.\""),
               .direct("What happened after {V} fell?", "\"I helped {V.him} up and asked if {V.he} was hurt. I stayed until the ranger came.\""),
               .cross("Your dog was off its leash.", "\"I know. My dog was off its leash, and I should have had it on one.\""),
               .cross("{V} was hurt.", "\"I'm sorry about that. I'm sorry {V} was hurt.\""),
               .cross("{V} was hurt.", "\"I'm sorry about that. I'm sorry {V} was hurt.\""),
               .cross("A jogger saw you push {V} hard.", "\"It was not that hard. {V} lost footing on the gravel, and I did not mean for {V.him} to fall.\""),
               .cross("You were close enough to touch {V}.", "\"I was. {V} was swinging the leash near my dog's head, and I pushed {V.his} arm away.\"")],
        openings: ("{D}'s unleashed dog ran at {V}'s small dog in a county park. {V} yelled, {D} yelled back, and according to {V}, {D} shoved {V} to the ground, scraping {V.his} hands and bruising {V.his} hip.", "The defense will say {V} swung a leash at {D}'s dog first, a second walker saw it, and {D} pushed {V} away to protect the dog. {D} helped {V} up and stayed."),
        closings: ("An unleashed dog, a shouting match, and a shove that put {V} on the ground, seen by a jogger and recorded in an urgent care note.", "A man protecting his dog from a swung leash is not an aggressor. The State must prove {D} pushed {V} on purpose and not to defend the dog."),
        timeline: [(0, "Afternoon: dogs meet in the county park; the shove.")],
        identified: "Both stayed and deputies were called.", impact: "\"I don't walk my dog at that park anymore, and I used to go every morning. My hands were scraped raw when I was shoved to the ground, and my little dog was shaking. I just wanted somebody to keep a dog on a leash and treat people like neighbors.\"")

    static let stolenCarReport = FollowUpCases.followUp(
        key: "story.stolenCarReport", category: .publicOrder,
        headlines: ["Man Reported Car Stolen, Deputies Find It at Girlfriend's House", "False Stolen Car Report Charge"],
        law: "falseReport", threshold: 5, spec: "Willfully made a false report to law enforcement that {D.his} car had been stolen, on {DATE}.", ages: 20...56, victim: false,
        summary: "{D} called the sheriff's office on {DATE} to report a car stolen from outside {D.his} apartment. A deputy found the car two days later at {DL}'s girlfriend's house, parked behind a shed. {D.He} said the girlfriend had no right to take it. The girlfriend said {DL} had loaned it to her and filed the report after they broke up. {DL} says {D.he} truly believed the car was taken without permission.",
        state: [E(.document, 3, "911 Call", "{D}: \"Somebody took my car from outside my apartment.\""),
                E(.statement, 2, "Girlfriend's Statement", "She says {D} handed her the keys that week.")],
        defense: [E(.statement, 1, "Keys", "{D} says {D.he} never gave her the keys and she had a copy.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("Where did you find the car?", "\"Behind a shed at the girlfriend's house.\""),
               .direct("What did she say?", "\"That {DL} loaned it to her.\""),
               .direct("What did {D} report?", "\"That a car had been stolen from outside {D.his} apartment. {D.He} called the sheriff's office, and I took the report.\""),
               .direct("What did the girlfriend say?", "\"That {DL} had loaned her the car that week and handed her the keys. She said {D.he} later reported it stolen.\""),
               .direct("What did {DL} say?", "\"That {D.he} never gave her the keys and that she had a copy. {D.He} said {D.he} did not know where the car had gone.\""),
               .direct("What did you do after finding the car?", "\"I photographed it, ran the plate, and called {D.him}. I took statements from both {D.him} and the girlfriend that afternoon.\""),
                    .cross("{DL} may not have known she took it.", "\"That's what {D.he} says. {D.He} says {D.he} didn't know she took it.\""),
               .cross("A copy of the key existed.", "\"She had one. She had a copy of the key.\""),
               .cross("The girlfriend had a copy of the key?", "\"She said so. {DL} says {D.he} did not know that, and I have not been able to confirm either account.\""),
               .cross("A text said keep the car?", "\"A text from {D.him} to her said keep the car, but it was dated before the argument, and I do not know what it meant.\""),
                    .cross("{DL} could have forgotten lending the car?", "\"Possibly. I have no way to know what {D.he} remembers, and the text complicates it.\"")],
        theory: ("{D} reported a car stolen that {D.he} had loaned out.", "A real misunderstanding between exes."),
        allocution: "\"I truly believed my car was taken without my permission, and I did not know where it was. I called the sheriff's office because I was worried and angry. I now understand that my girlfriend had borrowed it. I'm sorry for wasting the deputies' time, and I'll make sure to speak with her first.\"",
        truths: ("{DL}'s text to her read, \"keep the car this week.\"", "{DL}'s girlfriend had taken the car with a spare key without asking."),
        defendant: [.direct("Why report it?", "\"It was gone. I didn't know where.\""),
               .direct("Did you loan it?", "\"No.\"", "\"I told her she could use it. Then we fought.\""),
               .direct("Why did you call the sheriff's office?", "\"The car was gone from outside my apartment. I did not know where it was, and I thought it had been stolen.\""),
               .direct("Who had keys to the car?", "\"I had mine. My girlfriend had a spare copy from when she drove it once. I had forgotten that.\""),
               .direct("Did you give her the keys that week?", "\"No. I did not hand her the keys. If she took the car, she took it with her own copy.\""),
               .direct("What did you do when you learned where it was?", "\"I called her, and she said I had loaned it to her. We argued, and I told the deputy the truth as I understood it.\""),
               .direct("How do you feel about the report?", "\"I made it in good faith. I did not know she had it, and I would not have wasted anyone's time.\""),
               .cross("A text says keep the car.", "\"That was before the fight.\""),
               .cross("Wasting deputies' time.", "\"I am truly sorry. I'm sorry for wasting the deputies' time.\""),
                    .cross("You did not check with your girlfriend before calling.", "\"I did not. I should have called her first, and I did not think of it.\""), .cross("You texted her to keep the car.", "\"I did, in a different context. That was weeks before.\""),
                    .cross("The car was at your girlfriend's house two days later.", "\"It was. I did not know that when I called, and I was surprised when the deputy told me.\"")],
        openings: ("{D} called the sheriff's office to report a car stolen from outside {D.his} apartment, and two days later a deputy found it behind a shed at {D}'s girlfriend's house. She said {D} had loaned it to her and handed her the keys.", "The defense will say {D} never gave her the keys, she had a copy, and {D} reported the car stolen in good faith because it was gone. {D} did not know where it was."),
        closings: ("A report of a stolen car, the car found at {D}'s girlfriend's house, a text saying keep the car, and her statement that {D} handed over the keys.", "A spare key and a bad argument explain an honest report. The State must prove {D} knew the car was not stolen when {D.he} called the sheriff."),
        timeline: [(0, "{DL} reports the car stolen."), (2, "Deputy finds it behind the girlfriend's shed.")],
        identified: "A deputy followed up on the report.", impact: nil)

    static let packageThief = FollowUpCases.followUp(
        key: "story.packageThief", category: .property,
        headlines: ["Doorbell Camera Catches Porch Package Thief", "Neighbors Share Video of Man Taking Parcels"],
        law: "misdLarceny", threshold: 5, spec: "Stole a package containing a pair of boots valued at $140 belonging to {V}, on {DATE}.", ages: 18...48, victim: true,
        summary: "On {DATE}, {V}'s doorbell camera recorded a man in a delivery-style vest picking up a package from the porch and walking off. Two other neighbors reported missing parcels the same week. {V} identified {D} from the video at the grocery store. {DL} says {D.he} was a delivery driver for an app and picked up the wrong porch by mistake.",
        state: [E(.video, 3, "Doorbell Camera", "A man in a delivery vest takes a package from the porch at 2:15 p.m. and leaves on foot."),
                E(.document, 2, "Other Reports", "Two other parcels reported missing on the same street that week.")],
        defense: [E(.document, 2, "Delivery App Record", "{D} made fourteen deliveries on the street that week.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("What does the video show?", "\"A man in a vest taking a box and leaving on foot, not in a delivery vehicle.\""),
               .direct("How did you identify {DL}?", "\"{V} saw {D.him} at the grocery store and called us.\""),
               .direct("How did you identify {DL}?", "\"{V} saw {D.him} at the grocery store and recognized the vest and the face from the video. {V} called us from the parking lot.\""),
               .direct("What other reports did you receive?", "\"Two neighbors on the same street reported missing parcels that same week, one on Tuesday and one on Thursday.\""),
               .direct("What does the delivery app show?", "\"That {DL} made fourteen deliveries on that street that week. It does not show a delivery to {V}'s address at that time.\""),
               .direct("What was in the package?", "\"A pair of boots {V} had ordered online. It was delivered to the porch that morning, and {V} found it missing at about three.\""),
                    .cross("{DL} delivers on that street.", "\"Yes, according to the app.\""),
               .cross("Mistakes happen.", "\"This one left on foot with no car.\""),
               .cross("{DL} was working on that street?", "\"According to the app, yes. A driver could pick up a package by mistake.\""),
               .cross("The video shows {DL} walking away, not running?", "\"He walked casually, with the box under his arm. He did not hide it.\""),
               .cross("You have no video of the other two thefts?", "\"No. Only {V}'s camera. The other two neighbors do not have cameras.\""),
                    .cross("{DL} looks like a delivery driver in the video?", "\"Yes. The vest and the walk are what a delivery driver would wear. That is why I asked about the app.\"")],
        theory: ("{D} took a package from a porch and left on foot.", "A delivery worker who took the wrong box."),
        allocution: "\"I deliver for an app, and I thought that package was mine to pick up. It wasn't, and I picked up the wrong porch by mistake. I'm sorry to {V}, and to the neighbors who were missing parcels. I should have double-checked the address. I'll return what I can and be more careful.\"",
        truths: ("The other two parcels were recovered in {DL}'s apartment.", "The vest belonged to another man who worked for the same app."),
        defendant: [.direct("What happened?", "\"I thought it was mine to pick up. It wasn't.\""),
               .direct("Why walk off?", "\"My car was around the corner.\""),
               .direct("What do you do for a living?", "\"I deliver for an app, mostly food and small boxes. I work a few hours a day and I walk a lot of porches.\""),
               .direct("Why did you pick up that package?", "\"I thought it was the one I was assigned. The porch had a box, and the label looked like the address on my screen.\""),
               .direct("What did you do with the package?", "\"I put it in my bag. I looked inside later and saw it was not what I was supposed to deliver.\""),
               .direct("What did the label say?", "\"I did not read it closely. It had a name and an address, and I thought it matched my route.\""),
                    .cross("Two other parcels.", "\"I don't know about those.\""),
               .cross("You opened it?", "\"I looked inside. I put it in my bag.\""),
               .cross("You looked inside.", "\"I did. I wanted to see what it was, and I should have taken it back.\""),
               .cross("You wore a delivery vest.", "\"I wear it every day for work. It was not a costume.\""),
                    .cross("You walked away with a package that was not yours.", "\"I did. I thought it was mine, and I should have looked at the name on the label.\"")],
        openings: ("A man in a delivery-style vest picked up a package from {V}'s porch at 2:15 p.m. and walked off on foot, and two other neighbors reported missing parcels the same week. {V} identified {D} from the video at the grocery store.", "The defense will say {D} is a delivery driver who works that street, mistook {V}'s box for an assigned package, and carried it to his car. A mistake is not a theft."),
        closings: ("A delivery vest, a porch, a box, and a man who left on foot with no delivery vehicle, plus two other missing parcels the same week.", "A delivery driver on fourteen stops that week who picked up the wrong box is a mistake. The State must prove {D} meant to take what was not {D.his}."),
        timeline: [(0, "2:15 p.m.: package taken from {V}'s porch.")],
        identified: "{V}'s doorbell camera and a chance sighting.", impact: "\"Now every delivery goes to my work address, because I can't trust my own porch. My doorbell camera showed a man in a delivery vest simply picking up the box and walking away. It was only a package, but it made me feel watched in my own home.\"")

    static let golfCartJoyride = FollowUpCases.followUp(
        key: "story.golfCartJoyride", category: .property,
        headlines: ["Teens Take Golf Cart for a Midnight Ride Through Subdivision", "Golf Cart Found in Pond After Joyride"],
        law: "misdLarceny", threshold: 5, spec: "Took and carried away a golf cart valued at $2,900 belonging to {V}, on {DATE}.", ages: 18...24, victim: true,
        summary: "{V}'s golf cart was taken from a carport near midnight on {DATE}, driven around a subdivision with its lights off, and abandoned in a retention pond. A neighbor's camera showed {D} and a friend riding on the cart. {DL} says the friend took it and {D.he} only hopped on for a ride.",
        state: [E(.video, 3, "Neighbor's Camera", "{D} riding on the back of the cart at 11:50 p.m."),
                E(.physical, 2, "The Cart", "Pulled from the pond, a total loss; the key was never in it.")],
        defense: [E(.statement, 1, "Friend", "{D} says the friend was driving and {D.he} didn't know it was taken.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("Who was on the cart?", "\"Two young men. {DL} was on the back.\""),
               .direct("What happened to the cart?", "\"Abandoned in a retention pond.\""),
               .direct("Where was the cart taken from?", "\"From a carport near {V}'s house, around midnight. {V} found it gone and the lights of the neighbor's house coming on.\""), .direct("What did the neighbor's camera show?", "\"Two young men riding the cart down the street with its lights off at 11:50 p.m. {DL} was on the back.\""), .direct("Where was the cart found?", "\"In a retention pond in the subdivision. It was pulled out, and it was a total loss.\""), .direct("What about the key?", "\"The key was never in it. Whoever took it started it some other way.\""),
                    .cross("{DL} wasn't driving.", "\"No. {DL} wasn't driving at any point that night.\""),
               .cross("The friend isn't charged.", "\"The friend isn't charged because we couldn't identify him.\""),
                    .cross("{DL} was not driving?", "\"No. {D.He} was on the back the whole time, according to the camera.\""), .cross("The friend has not been identified?", "\"We could not identify him. {DL} knows him and has not given us a full name.\""), .cross("A text from {DL} said look what we got?", "\"It did. {D.He} sent it to another friend during the ride.\"")],
        theory: ("{D} rode a stolen cart through the neighborhood and helped sink it.", "A passenger who didn't know it was stolen."),
        allocution: "\"I did not take that golf cart. A friend was driving, and I only hopped on for a ride. I should have said no and gotten off when I saw how it was being driven. I'm sorry to {V} for the cart in the pond. I'll help pay for what it cost.\"",
        truths: ("{DL}'s texts that night said, \"look what we got.\"", "The friend later came forward and said {DL} didn't know the cart was taken."),
        defendant: [.direct("Did you take it?", "\"No. My friend was driving.\""),
               .direct("Did you help push it?", "\"No.\"", "\"We pushed it. It was a joke.\""),
               .direct("What happened that night?", "\"My friend came by with a golf cart and told me to hop on. I did, and I thought it was his.\""),
               .direct("Did you know it was taken?", "\"No. He said it was his uncle's, and I did not ask. I was along for a ride.\""),
               .direct("What did you do while you were riding?", "\"I sat on the back and held on. I sent a text to a friend because I was excited.\""),
               .direct("How did it end up in the pond?", "\"My friend drove it in. I jumped off before it went in, and I ran home.\""),
               .direct("Why did you not tell anyone?", "\"I was scared. I did not know what to say, and I stayed home.\""),
               .cross("Texts say look what we got.", "\"The texts say look what we got because I was excited.\""),
               .cross("You rode it in the dark.", "\"I know. I rode it in the dark, and I shouldn't have.\""),
                    .cross("You rode on a cart you had not been given.", "\"I did. I did not ask whose it was, and I should have.\""), .cross("You jumped off before it went into the pond.", "\"I did. I did not want to be in the water, and I did not tell anyone afterward.\""),
                    .cross("The cart had no key, so someone started it another way.", "\"I do not know how. My friend started it, and I did not ask.\"")],
        openings: ("{V}'s golf cart was taken from a carport near midnight, driven around a subdivision with its lights off, and abandoned in a retention pond. A neighbor's camera shows {D} riding on the back of the cart with a friend.", "The defense will say {D} was invited by a friend who said the cart was his uncle's, never drove it, and jumped off before it went into the pond."),
        closings: ("A taken golf cart, a ride with the lights off, a text saying 'look what we got,' and a cart left in a pond, with {D} on the back.", "{D} sat on the back of a friend's cart believing it was his uncle's. The State must prove {D} knew it was taken."),
        timeline: [(0, "11:50 p.m.: cart taken; later found in the pond.")],
        identified: "A neighbor's camera.", impact: "\"It was my husband's pride, and he kept it spotless for years. Someone took it from our carport at midnight, drove it with the lights off, and left it in a pond. We can't replace it, and he can't bring himself to look at what's left.\"")

    static let refusedID = FollowUpCases.followUp(
        key: "story.refusedID", category: .publicOrder,
        headlines: ["Man Refuses to Give Name to Deputy, Charged With Resisting", "Park Stop Ends in Arrest Over Refused ID"],
        law: "resisting", threshold: 5, spec: "Willfully resisted, delayed, and obstructed a public officer, a sheriff's deputy, by refusing to identify {D.himself} during a lawful stop, on {DATE}.", ages: 24...60, victim: false,
        summary: "A deputy approached {D} sitting in a parked car at a closed county park at 11 p.m. on {DATE}. {DL} refused to give a name or show ID, saying, \"I know my rights.\" The deputy ordered {DL} out of the car; {DL} refused, rolled up the window, and was arrested. {DL} says the park had no sign about closing hours and that the deputy had no reason to stop {D.him}.",
        state: [E(.video, 3, "Body Camera", "The deputy asks four times for a name and ID; {D} refuses each time."),
                E(.document, 2, "Park Hours", "The park closes at dusk; a sign at the entrance says so.")],
        defense: [E(.statement, 1, "No Sign", "{D} says the entrance sign was behind a bush.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("Why did you approach?", "\"A car in a closed park at 11 p.m.\""),
               .direct("What did {DL} do?", "\"Refused my questions four times and rolled up the window.\""),
               .direct("What was the park's status?", "\"It closes at dusk, and a sign at the entrance says so. The sign is posted on a post by the gate, partly behind a shrub.\""),
               .direct("What time did you approach {DL}?", "\"About 11 p.m. The car was parked inside the gate near the picnic shelter, with the engine off and the lights on.\""),
               .direct("What did you ask {DL}?", "\"His name and identification. I asked four times, and I explained that the park was closed.\""),
               .direct("What did {DL} do?", "\"Refused each time, rolled up the window, and would not step out when I ordered it. I arrested him for failure to leave a closed park.\""),
               .cross("{DL} stayed calm.", "\"Yes. {DL} stayed calm the whole time.\""),
               .cross("Was {D.he} violating a law?", "\"Trespass, once I confirmed the closing sign.\""),
               .cross("The sign is partly behind a bush?", "\"It is partly covered by a shrub. I did not photograph it at night.\""),
               .cross("{DL} was not committing another crime?", "\"Not that I knew. He was sitting in a parked car in a closed park.\""),
               .cross("The park gate was open that night?", "\"It was. Nothing blocked the entrance, and the closing sign is posted beside it, partly behind the shrub.\"")],
        theory: ("{D} refused four lawful requests and shut the window on a deputy.", "A man who stayed calm and exercised his rights."),
        allocution: "\"I was sitting in my car at a closed park, and I know my rights. I did not think I'd done anything wrong, so I refused to give my name or step out. I understand now that I made it harder for the deputy. I'm sorry for rolling up the window, and I'll be more cooperative.\"",
        truths: ("{DL} had a bag of pills in the console and wanted to avoid a search.", "The park sign was indeed hidden by brush, photos showed."),
        defendant: [.direct("Why didn't you give your name?", "\"I know my rights and I didn't do anything wrong.\""),
               .direct("Did you know the park was closed?", "\"I didn't see the sign.\""),
               .direct("Why were you at the park?", "\"I wanted to sit somewhere quiet and think. I was parked near the picnic shelter, and I did not see anyone.\""),
               .direct("Did you see the closing sign?", "\"No. It was behind a bush at the entrance, and it was dark. I did not know the park was closed.\""),
               .direct("Why did you refuse to give your name?", "\"I know my rights and I did not do anything wrong. I did not think a deputy could make me identify myself in a parked car.\""),
               .direct("Why did you roll up the window?", "\"I felt unsafe. The deputy was shining a light in my face and shouting, and I wanted some distance.\""),
               .cross("Four requests.", "\"I said no each time.\""),
               .cross("You rolled up the window.", "\"I rolled up the window because I felt unsafe.\""),
               .cross("The park closes at dusk.", "\"I know that now. I did not know it that night.\""),
                    .cross("The park is closed at dusk.", "\"I know that now. I did not know it that night.\""),
                    .cross("The deputy told you four times that the park was closed.", "\"He did, and I believed him by the fourth time. I should have left then.\"")],
        openings: ("A deputy approached {D} sitting in a parked car at a closed county park at 11 p.m., and {D} refused to give a name or show ID, saying, 'I know my rights.' The deputy ordered {D} out, {D} rolled up the window, and was arrested.", "The defense will say the entrance sign was behind a bush, {D} did not know the park was closed, and {D} is not required to identify himself while sitting in a parked car. {D} stayed calm."),
        closings: ("Four requests for a name, four refusals, a closed park with a posted sign, and a window rolled up on a deputy. {D} was ordered out and would not move.", "A man who did not see the sign sat in a quiet park and kept his rights. The State must prove {D} knew the park was closed and knowingly defied the deputy."),
        timeline: [(0, "11 p.m.: deputy approaches the parked car.")],
        identified: "The deputy's body camera.", impact: nil)

    static let oxyBottle = FollowUpCases.followUp(
        key: "story.oxyBottle", category: .drugs,
        headlines: ["Woman Carried Mother's Pain Pills in Her Purse, Deputies Say", "Prescription Bottle in Another Name Leads to Arrest"],
        law: "possSchedII", threshold: 5, spec: "Knowingly possessed oxycodone, a Schedule II controlled substance, on {DATE}.", ages: 25...64, victim: false,
        summary: "A deputy stopped {D} for a broken tail light on {DATE}. A pill bottle in {DL}'s purse had another person's name on the label: {DL}'s mother, with 38 oxycodone tablets. {DL} says {D.he} was picking up the prescription for {D.his} mother, who is bedridden, and was on the way to deliver it.",
        state: [E(.physical, 3, "The Bottle", "A pharmacy bottle labeled with {D}'s mother's name; 38 oxycodone tablets.", .search),
                E(.document, 2, "Pharmacy Record", "The prescription was picked up by {D} that afternoon.")],
        defense: [E(.document, 3, "Mother's Records", "The mother's doctor confirms the prescription and that she is bedridden.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("What did you find?", "\"A pill bottle with 38 oxycodone, labeled for {D.his} mother.\""),
               .direct("What did {D.he} say?", "\"That {D.he} was bringing it to {D.his} mother.\""),
               .direct("Why did you stop {DL}?", "\"For a broken tail light on a county road. I explained the reason, and {D.he} pulled over right away.\""),
               .direct("What did you see in the purse?", "\"A pharmacy pill bottle with another person's name on the label: {D.his} mother. It held 38 oxycodone tablets.\""),
               .direct("What did {DL} say?", "\"That {D.he} had picked up the prescription for {D.his} mother, who is bedridden, and was on the way to deliver it.\""),
               .direct("How did you verify that?", "\"I called the pharmacy, and the record shows {D} picked it up that afternoon. The mother's doctor confirmed the prescription and that she cannot leave her bed.\""),
               .cross("The label matched the pharmacy.", "\"It did. The label matched the pharmacy.\""),
               .cross("{DL} was cooperative.", "\"Very. {DL} was very cooperative.\""),
               .cross("{DL} was cooperative?", "\"Very. {D.He} handed over the purse before I asked and answered every question.\""),
               .cross("Did you count the tablets?", "\"I did, on the roadside. The count was 38, which is what the label said.\""),
                    .cross("The mother's doctor confirms the prescription?", "\"Yes. The doctor's office confirmed the order and that she is bedridden.\"")],
        theory: ("{D} had 38 oxycodone pills in a bottle that wasn't hers.", "A daughter running an errand for a bedridden mother."),
        allocution: "\"I picked up that bottle for my mother, who can't leave her bed. I was on my way to bring it to her when I was stopped for a tail light. I never meant to carry medicine that was not mine for any reason but that. I'm sorry for the confusion, and I'd ask the court to speak to her doctor.\"",
        truths: ("{DL} had been taking some of her mother's pills, a pill count showed.", "The pharmacy had told {DL} to pick up the prescription for her mother."),
        defendant: [.direct("Why did you have the bottle?", "\"I picked it up for my mother. She can't leave the bed.\""),
               .direct("Did you take any?", "\"No.\"", "\"A few, for my back.\""),
               .direct("What were you doing that afternoon?", "\"Picking up my mother's prescription. She cannot leave the bed, and I handle her medicines.\""),
               .direct("Where were you going?", "\"To her house across town. I was going to give her the first dose and set up her pill box.\""),
               .direct("Why was the bottle in your purse?", "\"It was the safest place. I did not want it rolling around on the seat or in the trunk.\""),
               .direct("Did you take any of the tablets?", "\"No. I have never taken them, and I did not open the bottle.\""),
               .direct("How did you feel when the deputy stopped you?", "\"Nervous but honest. I told him right away it was my mother's and that I was bringing it to her.\""),
               .cross("The prescription isn't yours.", "\"No. The prescription isn't mine.\""),
               .cross("Was the count right?", "\"I didn't count what was there.\""),
                    .cross("You were driving with a bottle of narcotics in your purse.", "\"I was, and I would do it again for my mother. I have the right to bring her medicine.\""),
                    .cross("The bottle was in your purse, not in your mother's hand.", "\"It was. I was carrying it because I was taking it to her. I did not think I was doing anything wrong.\""), .cross("A deputy found you with a controlled substance.", "\"I did. I understood that, and I told him it was my mother's before he asked.\"")],
        openings: ("A deputy stopped {D} for a broken tail light and found a pharmacy bottle in {D}'s purse labeled with {D}'s mother's name, holding 38 oxycodone tablets. {D} says {D.he} was delivering it to {D.his} mother, who is bedridden.", "The defense will say {D} picked up the prescription that afternoon for a bedridden mother, kept it in {D.his} purse, and was on the way to deliver it. The pharmacy and the doctor confirm it."),
        closings: ("A bottle with someone else's name, 38 oxycodone tablets, a purse, and a driver stopped on a county road, with the pharmacy label matching the doctor's order.", "The pharmacy, the doctor and the label all confirm the bottle was {D}'s mother's, and {D} was on the way to her. The State must prove {D} was not authorized to carry it."),
        timeline: [(0, "Afternoon: pharmacy pickup; evening: traffic stop.")],
        identified: "A traffic stop.", impact: nil, doctrines: ["searchSeizure", "burdenOfProof"])

    static let dineDash = FollowUpCases.followUp(
        key: "story.dineDash", category: .property,
        headlines: ["Customers Skip Out on $74 Diner Bill", "Dine-and-Dash Suspect Caught Through License Plate"],
        law: "misdLarceny", threshold: 5, spec: "Stole $74 in food and service from a diner, on {DATE}.", ages: 19...50, victim: false,
        summary: "{D} and a friend ate a $74 meal at a diner on {DATE}, and while the waitress was in the kitchen, walked out the front door and drove away. The diner's camera caught the plate. {DL} says the waitress had told them to pay at the counter and they had been looking for the register.",
        state: [E(.video, 3, "Diner Camera", "Two people stand, walk out without stopping at the register, and leave in a car."),
                E(.document, 2, "Check", "Unpaid $74 check, table nine.")],
        defense: [E(.statement, 1, "Counter", "{D} says the counter was unmanned and they waited.")],
        witnessRole: "Diner waitress",
        exam: [.direct("What happened?", "\"They finished, stood up, and left. I was in the kitchen.\""),
               .direct("Was the counter manned?", "\"There's a bell. They didn't ring it.\""),
               .direct("What did the table order?", "\"A $74 meal for two: two entrees, an appetizer and drinks. They sat at table nine for about an hour.\""), .direct("What did you do while they ate?", "\"I refilled their drinks, checked on them twice, and then went to the kitchen to pick up another table's order.\""), .direct("What happened next?", "\"When I came back, the table was empty. The check was on the table, unpaid, and I saw the car leave through the front window.\""), .direct("How did you get the plate?", "\"The camera over the register caught the car as it pulled out, and the plate was readable. I gave it to the manager.\""),
                    .cross("They may have been looking for the register.", "\"The register is right by the door.\""),
               .cross("{DL} came back?", "\"No. {DL} didn't come back.\""),
                    .cross("The counter had a bell for payment, didn't it?", "\"There is a bell on the counter, and the register is right by the door. They did not ring it.\""), .cross("{DL} says the counter was unmanned?", "\"I was in the kitchen, and the cashier was on break. That may be true for a minute.\""), .cross("You did not tell them to pay at the counter?", "\"I told them the check was on the table and to pay up front when they were ready.\"")],
        theory: ("{D} ate a meal and left without paying.", "A misunderstanding about where to pay."),
        allocution: "\"My friend told me we'd paid, and the waitress said to pay at the counter, so we were looking for the register. We never meant to run out on that diner bill. I should have made sure before leaving. I'm sorry to the waitress, and I'll pay the seventy-four dollars right away.\"",
        truths: ("The two had left unpaid checks at three diners in the month.", "{D.His} friend told {D.him} they'd paid on the app, and {D} believed it."),
        defendant: [.direct("Why did you leave?", "\"My friend said we'd paid.\""),
               .direct("Did you see the register?", "\"I didn't look at the register.\""),
               .direct("What were you doing at the diner?", "\"Having dinner with a friend. We had been there before, and we ordered a regular meal.\""),
               .direct("Why did you leave?", "\"My friend said we had paid. I did not check, and I walked out with him.\""),
               .direct("Did you see the register?", "\"I never looked at it closely. I followed him to the front door and out to the car.\""),
               .direct("What did you do afterward?", "\"I asked my friend, and he said he would take care of it. I did not call the diner.\""),
               .cross("You never came back.", "\"I never came back because I was scared.\""),
               .cross("The register is by the door.", "\"I know. The register is by the door.\""),
               .cross("The waitress was in the kitchen when you left.", "\"I did not see her. I did not think I had to stop and tell her.\""),
                    .cross("You left while the waitress was in the kitchen.", "\"I did. I should have waited for her, and I did not.\""),
                    .cross("You never paid the $74.", "\"My friend did later. I know that is not an excuse, and I should have gone back myself.\"")],
        openings: ("{D} and a friend ate a $74 meal at a diner, and while the waitress was in the kitchen, walked out the front door and drove away. The diner's camera caught the plate.", "The defense will say the waitress told them to pay at the counter, and they were looking for the register, which was unmanned. {D} believed {D.his} friend had paid."),
        closings: ("A $74 check, an empty table, a car leaving, and a plate on the camera, with a register by the front door that no one stopped at.", "A friend who said he had paid and a counter that was unmanned for a minute. The State must prove {D} walked out of the diner meaning to avoid the bill."),
        timeline: [(0, "Evening: the meal and the walk-out.")],
        identified: "The diner's camera and plate.", impact: nil)

    static let fenceKick = FollowUpCases.followUp(
        key: "story.fenceKick", category: .property,
        headlines: ["Neighbor Dispute Over Property Line Ends With Broken Fence", "Man Charged After Kicking In Neighbor's Fence"],
        law: "injuryRealProperty", threshold: 5, spec: "Willfully and wantonly damaged real property of {V}, a wooden privacy fence, causing damage of $850, on {DATE}.", ages: 30...68, victim: true,
        summary: "{V} built a privacy fence on {V.his} side of what {D} believes is {DL}'s property line. On {DATE}, {DL} kicked in six boards and pulled two posts loose with a truck chain. {V}'s doorbell camera recorded the whole thing. A survey later put the fence two feet over {V}'s own line. {DL} says {D.he} warned {V} first and had every right.",
        state: [E(.video, 3, "Doorbell Camera", "{D} kicks in boards and pulls posts with a chain on a Saturday morning."),
                E(.document, 2, "Repair Estimate", "$850 to replace six boards and two posts.")],
        defense: [E(.document, 2, "Survey", "A survey puts the fence about two feet over the line, onto {D}'s side.")],
        witnessRole: "Sheriff's deputy",
        exam: [.direct("What did you see?", "\"A fence with six boards kicked in and two posts pulled.\""),
               .direct("What did {DL} say?", "\"That it was on {D.his} land.\""),
               .direct("What did you find at {V}'s house?", "\"A fence with six boards kicked in and two posts pulled loose, with a chain still hanging from one of them.\""),
               .direct("What does the doorbell camera show?", "\"It shows {D} walking up on a Saturday morning, kicking in boards, then hooking a chain to a truck and pulling two posts.\""),
               .direct("What was the damage?", "\"$850 to replace six boards and two posts. {V} gave us the estimate from a fence company.\""),
               .direct("What did the survey show?", "\"That the fence is about two feet over the line, onto {D.his} side. The survey was done after the incident.\""),
               .cross("The survey shows it's over the line.", "\"By two feet, which is what I told {V} before I kicked anything.\""),
               .cross("That's a civil dispute.", "\"The dispute may be civil, but the damage isn't.\""),
               .cross("This is a civil dispute, isn't it?", "\"The boundary dispute may be civil. The damage to the fence is what we charged.\""),
               .cross("{DL} warned {V} before?", "\"{D.He} says {D.he} warned {V} twice. {V} says {V.he} remembers one warning.\""),
                    .cross("A doorbell camera recorded the whole thing?", "\"It did. It shows the boards being kicked and the chain being pulled.\"")],
        theory: ("{D} destroyed a neighbor's fence. A boundary dispute is for a civil court.", "A fence that was on {D}'s land, taken down after a warning."),
        allocution: "\"I believe that fence was on my property, and {V} wouldn't move it. I kicked in the boards and pulled the posts with a chain, and I lost my temper. A survey says I was wrong, and I accept that. I'm sorry for the damage, and I'll rebuild it or pay for it.\"",
        truths: ("{DL}'s truck chain had paint from the fence.", "The survey had been available to {V} for a year and {V} refused to read it."),
        defendant: [.direct("Why did you take it down?", "\"It was on my property and {V} wouldn't move it.\""),
               .direct("Did you warn {V}?", "\"Twice. I warned {V} twice.\""),
               .direct("What was your problem with the fence?", "\"It was on my land. {V} built it two feet over the line, and {V} would not move it.\""),
               .direct("Why did you use a chain?", "\"It was the quickest way. I did not want to wait, and I was angry.\""),
               .direct("What did you think when the survey came back?", "\"That I was right. The fence was over the line, and I felt justified.\""),
               .direct("Did you warn {V} before you pulled it down?", "\"Twice. I told {V} to move it, and {V} did not.\""),
               .direct("What did you tell the deputy when he arrived?", "\"That I had pulled down a fence that was over my line, and that I had a survey I was going to get done to prove it. I did not argue with him.\""),
                    .cross("You used a chain.", "\"It was the quickest way.\""),
               .cross("A survey is a civil matter.", "\"I know. A survey is a civil matter, and I understand that.\""),
               .cross("The fence cost $850 to fix.", "\"I know. I will pay for it if the court says I should.\""),
                    .cross("You waited until Saturday morning to do it.", "\"I did. I thought {V} would be asleep, and I did not want a fight.\""),
                    .cross("The camera shows you kicking six boards in a row.", "\"It does. I was angry, and I kicked until they gave way.\"")],
        openings: ("{V} built a privacy fence on {V.his} side of what {D} believes is the property line, and on a Saturday morning {D} kicked in six boards and pulled two posts loose with a truck chain. {V}'s doorbell camera recorded it.", "The defense will say a later survey put the fence about two feet over the line, onto {D}'s side, and {D} had warned {V} twice. {D} believed {D.he} was removing a fence that did not belong there."),
        closings: ("A chain on a truck, six boards kicked in, two posts pulled, $850 of damage, and the whole thing on camera. {D} took the law into {D.his} own hands.", "The fence was over the line, and a boundary dispute is not a crime. The State must prove {D} knew the fence was {V}'s and meant to damage it."),
        timeline: [(0, "Saturday morning: fence boards kicked in; posts pulled.")],
        identified: "{V}'s doorbell camera.", impact: "\"It was a privacy fence I'd saved up for, and now it's a pile of boards in the grass. I watched on my doorbell camera while someone kicked in six boards and dragged posts loose with a chain. It cost me hundreds of dollars and a lot of sleep.\"")

    static let walletCard = FollowUpCases.followUp(
        key: "story.walletCard", category: .whiteCollar,
        headlines: ["Man Used Found Credit Card at Gas Pumps, Prosecutors Say", "Lost Wallet Leads to Four Card Charges"],
        law: "cardFraud", threshold: 5, spec: "Used a credit card belonging to {V}, a card issued in another person's name, to obtain $212 in goods and services, without consent, on {DATE}.", ages: 19...55, victim: true,
        summary: "{V} lost a wallet at a grocery store on {DATE}. Within two hours, the credit card inside was used four times: twice at a gas station and twice at a convenience store, for $212 total. The gas station camera showed {D} swiping the card. {DL} says {D.he} found the wallet in a parking lot, meant to turn it in, and used the card only to buy gas to drive to the sheriff's office.",
        state: [E(.video, 3, "Gas Station Camera", "{D} swipes the card at the pump and again at the door."),
                E(.document, 2, "Card Statement", "Four charges totaling $212 within two hours of the loss.")],
        defense: [E(.statement, 1, "Finder's Account", "{D} says {D.he} meant to take the wallet to the sheriff.")],
        witnessRole: "Sheriff's detective",
        exam: [.direct("What did the camera show?", "\"{DL} using the card four times in two hours.\""),
               .direct("Did {DL} turn in the wallet?", "\"No. We found it in {D.his} car.\""),
               .direct("How was the wallet lost?", "\"{V} lost it at a grocery store. The card inside was used four times within two hours, for $212.\""),
               .direct("Where was the card used?", "\"Twice at a gas station and twice at a convenience store. The gas station camera shows {D} swiping the card at the pump and again at the door.\""),
               .direct("Where was the wallet found?", "\"In {DL}'s car, when we stopped it. The wallet was in the center console, with {V}'s license and two other cards inside.\""),
               .direct("What did {DL} say?", "\"That {D.he} found the wallet in a parking lot and meant to take it to the sheriff. {D.He} said {D.he} used the card for gas to get there.\""),
               .cross("{D.He} used it for gas.", "\"{D.He} used it for gas and at a convenience store.\""),
               .cross("{D.He} had no earlier record.", "\"None. {D.He} had no earlier record.\""),
               .cross("{DL} did not try to hide?", "\"{D.He} used the card in front of cameras, and {D.he} kept the wallet in the open console.\""),
                    .cross("{DL} cooperated with you at the traffic stop?", "\"Fully. {D.He} told me about the wallet before I asked.\""),
                    .cross("The wallet was recovered in {DL}'s vehicle?", "\"It was, in the center console. The license and two other cards were still inside.\""), .cross("{DL} was not hiding the wallet?", "\"No. It was in the open console, not under a seat.\"")],
        theory: ("{D} found a wallet and used the card four times.", "A finder who made a mistake on the way to the sheriff."),
        allocution: "\"I found that wallet in a parking lot, and I meant to turn it in. I used the card to buy gas so I could drive to the sheriff's office, and I should not have. I'm sorry to {V} for the charges. I'll repay the two hundred twelve dollars and the trouble.\"",
        truths: ("The wallet's cash was gone and {DL} had spent it on cigarettes.", "{DL} returned the wallet to the sheriff the next morning, though only after a call."),
        defendant: [.direct("How did you find the wallet?", "\"I found the wallet in the parking lot.\""),
               .direct("Why use the card?", "\"I needed gas to get to the sheriff's office.\""),
               .direct("Where did you find the wallet?", "\"In the parking lot of the grocery store. It was lying next to my car, and no one was around.\""),
               .direct("What did you plan to do with it?", "\"Take it to the sheriff's office. I was going to turn it in, and I needed gas to get there.\""),
               .direct("Why did you use it four times?", "\"Twice for gas, and twice for snacks. I was hungry, and I was not thinking clearly.\""),
               .direct("What happened to the cards inside the wallet?", "\"They were all there except the one I used. I did not touch the others.\""),
               .cross("Four times.", "\"Twice for gas. Twice for snacks.\""),
               .cross("You kept the wallet.", "\"I was going to return it.\""),
               .cross("You never went to the sheriff.", "\"I did not get there. I was stopped before I did.\""),
               .cross("You used the card at the door of the store as well.", "\"I did. I stopped for a drink on my way to the sheriff.\""),
               .cross("The wallet had a driver's license in it with a name and address.", "\"It did. I saw it, and I meant to look it up, but I used the card first.\"")],
        openings: ("{V} lost a wallet at a grocery store, and within two hours the credit card inside was used four times, twice at a gas station and twice at a convenience store, for $212. The gas station camera shows {D} swiping the card, and the wallet was in {D}'s car.", "The defense will say {D} found the wallet in a parking lot, meant to take it to the sheriff, and used the card for gas to get there. {D} kept the wallet in the open and used the card in front of cameras."),
        closings: ("Four charges in two hours, the camera at the pump, and the wallet in {D}'s console, with {V}'s license and other cards still inside. A man who finds a wallet and means to return it does not run up the card.", "A man who finds a wallet and means to return it does not use the card four times. The State must prove {D} knew the card was not {D.his} to use."),
        timeline: [(0, "Wallet lost; four charges in two hours.")],
        identified: "The gas station camera and the card number.", impact: "\"I canceled every card I had, and it took a week to get my life back in order. The card in my lost wallet was used four times in two hours for over two hundred dollars. I spent hours on the phone with the bank and I'm still checking my statements.\"")
}
